    $db->query("INSERT INTO atributos_tipo_evidencia (id_tipo_evidencia,id_tipo_atributo,nombre_atributo,slug,requerido,multiple) VALUES ($tipoAtributos,$textoTipo,'Obligatorio','obligatorio',1,0),($tipoAtributos,$textoTipo,'Opcional','opcional',0,0)");
    $idReq=(int)$db->query("SELECT id_ate FROM atributos_tipo_evidencia WHERE id_tipo_evidencia=$tipoAtributos AND slug='obligatorio'")->fetch_row()[0];
    $idOpt=(int)$db->query("SELECT id_ate FROM atributos_tipo_evidencia WHERE id_tipo_evidencia=$tipoAtributos AND slug='opcional'")->fetch_row()[0];
    $db->query("INSERT INTO evidencias (id_docente,id_tipo_evidencia,titulo,archivo) VALUES (2,$tipoAtributos,'Edición atributos','temporal.pdf')"); $idAttrs=$db->insert_id;
    $postAttrs=['id_evidencia'=>$idAttrs,'indice'=>[$idReq=>[1],$idOpt=>[1]],'valor_texto'=>[$idReq=>[''], $idOpt=>['']]];
    comprobar(endpoint('evidencia-detalle-save.php',2,4,$postAttrs)['status']==='error','Atributo obligatorio vacío impide guardar');
    $postAttrs['valor_texto'][$idReq]=['Capturado'];
    comprobar(endpoint('evidencia-detalle-save.php',2,4,$postAttrs)['status']==='ok','Atributo opcional vacío permite guardar edición');
    comprobar((int)$db->query("SELECT COUNT(*) FROM evidencia_valores_atributo WHERE id_evidencia=$idAttrs AND id_ate=$idOpt")->fetch_row()[0]===0,'Atributo opcional vacío no se persiste como valor capturado');
    comprobar(endpoint('evidencia-detalle-get.php',2,4,[],['id'=>$idAttrs])['status']==='ok','Consulta de evidencias y atributos existentes disponible');
    $db->query("INSERT INTO instrumento_tipo_evidencia (id_instrumento,id_tipo_evidencia) VALUES (1,$tipoAtributos)");
    comprobar(endpoint('evaluacion-save.php',1,1,['id_evidencia'=>$idAttrs,'id_instrumento'=>1,'resultado'=>'8'])['status']==='ok','Atributo opcional vacío no impide completar ni evaluar la evidencia');
    $db->query("UPDATE usuarios SET rol=3 WHERE id_usuario=$uid");
    $db->query("INSERT INTO evaluador_instrumento (id_evaluador,id_instrumento) VALUES ($uid,1)");
    $historyBefore=(int)$db->query("SELECT COUNT(*) FROM historial_evaluaciones h JOIN evaluaciones_versionadas v ON v.id_evaluacion=h.id_evaluacion WHERE v.id_usuario_eval=$uid")->fetch_row()[0];
    $sinCsrfEliminar=endpoint('usuario-eliminar.php',1,1,['id_usuario'=>$uid],[],true,'missing');
    comprobar(($sinCsrfEliminar['code']??'')==='csrf_invalid' && (int)$db->query("SELECT activo FROM usuarios WHERE id_usuario=$uid")->fetch_row()[0]===1,'La desactivación administrativa rechaza POST sin CSRF y no cambia la cuenta');
    $autoEliminar=endpoint('usuario-eliminar.php',1,1,['id_usuario'=>1]);
    comprobar($autoEliminar['status']==='error' && (int)$db->query('SELECT activo FROM usuarios WHERE id_usuario=1')->fetch_row()[0]===1,'La cuenta no puede desactivarse a sí misma');
    $protegerSuper=endpoint('usuario-eliminar.php',4,2,['id_usuario'=>1]);
    comprobar($protegerSuper['status']==='error' && (int)$db->query('SELECT activo FROM usuarios WHERE id_usuario=1')->fetch_row()[0]===1,'Un administrador regular no puede desactivar al Super Usuario');
    $desactivar=endpoint('usuario-eliminar.php',1,1,['id_usuario'=>$uid]);
    comprobar($desactivar['status']==='ok' && $desactivar['action']==='deactivated' && (int)$db->query("SELECT activo FROM usuarios WHERE id_usuario=$uid")->fetch_row()[0]===0,'La acción administrativa desactiva la cuenta mediante la interfaz segura del endpoint');
    comprobar((int)$db->query("SELECT COUNT(*) FROM historial_evaluaciones h JOIN evaluaciones_versionadas v ON v.id_evaluacion=h.id_evaluacion WHERE v.id_usuario_eval=$uid")->fetch_row()[0]===$historyBefore,'Desactivar usuario conserva el historial de sus evaluaciones');
    comprobar((int)$db->query("SELECT COUNT(*) FROM evaluador_instrumento WHERE id_evaluador=$uid")->fetch_row()[0]===0,'Desactivar revoca las asignaciones del evaluador');
    $vistaInactiva=endpoint('vista-gestion-usuarios.php',1,1,[],[],false);
    comprobar(strpos($vistaInactiva,'Reactivar')!==false,'La lista ofrece el mismo botón para reactivar una cuenta inactiva');
    $reactivar=endpoint('usuario-eliminar.php',1,1,['id_usuario'=>$uid,'accion'=>'activar']);
    comprobar($reactivar['status']==='ok' && $reactivar['action']==='activated' && (int)$db->query("SELECT activo FROM usuarios WHERE id_usuario=$uid")->fetch_row()[0]===1,'El mismo endpoint reactiva la cuenta cuando su estado es inactivo');
    comprobar((int)$db->query("SELECT COUNT(*) FROM evaluador_instrumento WHERE id_evaluador=$uid")->fetch_row()[0]===0,'La reactivación requiere configurar nuevamente las asignaciones de evaluador');
    $altaEstado=endpoint('instrumento-insert.php',1,1,['abreviatura'=>'BAJAPRUEBA','nombre_completo'=>'Instrumento temporal con relaciones']);
    $estadoId=(int)$altaEstado['id'];
    $db->query("INSERT INTO instrumento_tipo_evidencia (id_instrumento,id_tipo_evidencia) VALUES ($estadoId,1)");
    $db->query("INSERT INTO evaluador_instrumento (id_evaluador,id_instrumento) VALUES ($uid,$estadoId)");
    $sinTokenBaja=endpoint('instrumento-eliminar.php',1,1,['id_instrumento'=>$estadoId,'accion'=>'desactivar'],[],true,'missing');
    comprobar(($sinTokenBaja['code']??'')==='csrf_invalid' && (int)$db->query("SELECT activo FROM instrumentos WHERE id_instrumento=$estadoId")->fetch_row()[0]===1,'La baja de instrumentos rechaza POST sin token CSRF');
    $bajaInstrumento=endpoint('instrumento-eliminar.php',1,1,['id_instrumento'=>$estadoId,'accion'=>'desactivar']);
    comprobar($bajaInstrumento['status']==='ok' && (int)$db->query("SELECT activo FROM instrumentos WHERE id_instrumento=$estadoId")->fetch_row()[0]===0,'La acción Eliminar desactiva el instrumento sin borrarlo físicamente');
    comprobar((int)$db->query("SELECT COUNT(*) FROM instrumento_tipo_evidencia WHERE id_instrumento=$estadoId")->fetch_row()[0]===1 && (int)$db->query("SELECT COUNT(*) FROM evaluador_instrumento WHERE id_instrumento=$estadoId")->fetch_row()[0]===1,'La baja conserva relaciones documentales y de evaluadores');
    $altaInstrumento=endpoint('instrumento-eliminar.php',1,1,['id_instrumento'=>$estadoId,'accion'=>'activar']);
    comprobar($altaInstrumento['status']==='ok' && (int)$db->query("SELECT activo FROM instrumentos WHERE id_instrumento=$estadoId")->fetch_row()[0]===1,'El instrumento inactivo se puede restaurar desde la misma acción');
    $hardSinToken=endpoint('instrumento-eliminar-definitivo.php',1,1,['id_instrumento'=>$estadoId],[],true,'missing');
    comprobar(($hardSinToken['code']??'')==='csrf_invalid' && (int)$db->query("SELECT COUNT(*) FROM instrumentos WHERE id_instrumento=$estadoId")->fetch_row()[0]===1,'La eliminación permanente rechaza POST sin CSRF y conserva el instrumento');
    $hardDelete=endpoint('instrumento-eliminar-definitivo.php',1,1,['id_instrumento'=>$estadoId]);
    comprobar($hardDelete['status']==='ok' && (int)$db->query("SELECT COUNT(*) FROM instrumentos WHERE id_instrumento=$estadoId")->fetch_row()[0]===0,'Eliminar por completo borra instrumentos sin historial académico');
    comprobar((int)$db->query("SELECT COUNT(*) FROM instrumento_tipo_evidencia WHERE id_instrumento=$estadoId")->fetch_row()[0]===0 && (int)$db->query("SELECT COUNT(*) FROM evaluador_instrumento WHERE id_instrumento=$estadoId")->fetch_row()[0]===0,'La eliminación definitiva limpia solo las relaciones de configuración del instrumento');
    $hardHistorico=endpoint('instrumento-eliminar-definitivo.php',1,1,['id_instrumento'=>$iid]);
    comprobar($hardHistorico['status']==='error' && (int)$db->query("SELECT COUNT(*) FROM instrumentos WHERE id_instrumento=$iid")->fetch_row()[0]===1,'La eliminación permanente bloquea instrumentos con evaluaciones históricas');
    $emailBaja='docente-baja-'.bin2hex(random_bytes(4)).'@test.invalid';
    $st=$db->prepare("INSERT INTO usuarios (nombre,apellidop,apellidom,correo,password,rol,activo) VALUES ('Docente','Temporal','Baja',?, 'hash-temporal',4,1)");
    $st->bind_param('s',$emailBaja); $st->execute(); $docenteBaja=(int)$db->insert_id; $st->close();
    $archivoBaja='baja_usuario_'.bin2hex(random_bytes(6)).'.pdf';
    $rutaBaja=getcwd().'/uploads/files/'.$archivoBaja;
    if (!is_dir(dirname($rutaBaja))) mkdir(dirname($rutaBaja),0775,true);
    file_put_contents($rutaBaja,"archivo sintético de prueba\n");
    $st=$db->prepare("INSERT INTO evidencias (id_docente,id_tipo_evidencia,titulo,archivo) VALUES (?,?,'Evidencia temporal de baja',?)");
    $st->bind_param('iis',$docenteBaja,$tid,$archivoBaja); $st->execute(); $evidenciaBaja=(int)$db->insert_id; $st->close();
    $uiBaja=endpoint('vista-gestion-usuarios.php',1,1,[],[],false);
    comprobar(strpos($uiBaja,'Eliminar por completo')!==false && strpos($uiBaja,'openEliminarDefinitivoU')!==false,'La gestión de usuarios muestra la acción de eliminación permanente');
    $bajaSinCsrf=endpoint('usuario-eliminar-definitivo.php',1,1,['id_usuario'=>$docenteBaja],[],true,'missing');
    comprobar(($bajaSinCsrf['code']??'')==='csrf_invalid' && (int)$db->query("SELECT COUNT(*) FROM evidencias WHERE id_evidencia=$evidenciaBaja")->fetch_row()[0]===1,'La eliminación permanente rechaza POST sin CSRF y conserva las evidencias');
    $bajaCompleta=endpoint('usuario-eliminar-definitivo.php',1,1,['id_usuario'=>$docenteBaja]);
    comprobar($bajaCompleta['status']==='ok' && (int)$db->query("SELECT COUNT(*) FROM usuarios WHERE id_usuario=$docenteBaja")->fetch_row()[0]===0 && (int)$db->query("SELECT COUNT(*) FROM evidencias WHERE id_evidencia=$evidenciaBaja")->fetch_row()[0]===0,'La eliminación permanente permite borrar al docente aunque haya cargado evidencia');
    comprobar(!is_file($rutaBaja),'La eliminación retira el archivo privado huérfano');

    $emailHist='docente-hist-'.bin2hex(random_bytes(4)).'@test.invalid';
    $st=$db->prepare("INSERT INTO usuarios (nombre,apellidop,apellidom,correo,password,rol,activo) VALUES ('Docente','Temporal','Historial',?, 'hash-temporal',4,1)");
    $st->bind_param('s',$emailHist); $st->execute(); $docenteHist=(int)$db->insert_id; $st->close();
    $db->query("INSERT INTO evidencias (id_docente,id_tipo_evidencia,titulo,archivo) VALUES ($docenteHist,$tid,'Evidencia con historial','sin_archivo_temporal.pdf')"); $evidenciaHist=(int)$db->insert_id;
    $db->query("INSERT INTO evaluaciones_versionadas (id_evidencia,id_instrumento) VALUES ($evidenciaHist,1)");
    $bajaHist=endpoint('usuario-eliminar-definitivo.php',1,1,['id_usuario'=>$docenteHist]);
    comprobar($bajaHist['status']==='error' && (int)$db->query("SELECT COUNT(*) FROM usuarios WHERE id_usuario=$docenteHist")->fetch_row()[0]===1 && (int)$db->query("SELECT COUNT(*) FROM evidencias WHERE id_evidencia=$evidenciaHist")->fetch_row()[0]===1,'La eliminación protege evidencias con historial de evaluación');
    echo "$checks comprobaciones correctas.\n";
} finally {
    if ($creada) $db->query("DROP DATABASE `$nombre`");
    unlink($runner);
    if (is_file($rutaPrueba)) unlink($rutaPrueba);
}
